/**
 * `PulseCard(DATA)` from `levels`. The range bar only renders when every value it needs
 * (resistance, support, the two value-area bounds, fair value anchor, and the current price) is
 * present -- a partial bar showing the wrong relationships would be worse than no bar. The 4
 * numbers and the commentary paragraph render independently of the bar and of each other.
 *
 * This card groups 4 metrics at once, so per the "only show info if there's no higher view for
 * that indicator" rule, individual labels don't get their own tooltip -- the title's info icon
 * opens one bottom sheet covering whichever of the 4 are actually present.
 */
@Composable
fun KeyLevels(levels: DomainLevels?, price: Double?, modifier: Modifier = Modifier) {
    if (levels == null) return

    val pulseColors = LocalPulseColors.current
    var showGlossary by remember { mutableStateOf(false) }
    val title = stringResource(id = R.string.stock_detail_key_levels_title)

    PulseCard(style = PulseCardStyle.DATA, modifier = modifier.fillMaxWidth()) {
        Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
            DataCardTitleWithInfo(title = title, onInfoClick = { showGlossary = true })
            Spacer()

            Row(modifier = Modifier.fillMaxWidth()) {
                LevelStat(
                    modifier = Modifier.weight(1f),
                    value = levels.resistance,
                    label = stringResource(id = R.string.stock_detail_resistance_label),
                    valueColor = pulseColors.signalBearishText
                )
                LevelStat(
                    modifier = Modifier.weight(1f),
                    value = levels.support,
                    label = stringResource(id = R.string.stock_detail_support_label),
                    valueColor = pulseColors.signalBullishText
                )
            }
            Spacer()
            Row(modifier = Modifier.fillMaxWidth()) {
                LevelStat(
                    modifier = Modifier.weight(1f),
                    value = levels.fairValueAnchor,
                    label = stringResource(id = R.string.stock_detail_fair_value_anchor_label)
                )
                if (levels.accumulationZoneLow != null && levels.distributionZoneHigh != null) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = "$${formatPrice(levels.accumulationZoneLow)}–$${formatPrice(levels.distributionZoneHigh)}",
                            style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Text(
                            text = stringResource(id = R.string.stock_detail_value_area_label),
                            style = MaterialTheme.typography.labelSmall,
                            color = pulseColors.onSurfaceMuted
                        )
                    }
                }
            }

            if (
                levels.resistance != null && levels.accumulationZoneLow != null &&
                levels.distributionZoneHigh != null && levels.fairValueAnchor != null &&
                levels.support != null && price != null
            ) {
                Spacer()
                PriceRangeBar(
                    axisLow = levels.accumulationZoneLow,
                    axisHigh = levels.resistance,
                    valueAreaLow = levels.accumulationZoneLow,
                    valueAreaHigh = levels.distributionZoneHigh,
                    fairValueAnchor = levels.fairValueAnchor,
                    support = levels.support,
                    currentPrice = price
                )
            }

            levels.commentary?.let {
                Spacer()
                Text(
                    text = it,
                    style = MaterialTheme.typography.bodyMedium,
                    color = pulseColors.onSurfaceMuted
                )
            }
        }
    }

    if (showGlossary) {
        val entries = listOfNotNull(
            levels.resistance?.let { GlossaryEntry(stringResource(id = R.string.stock_detail_resistance_label), "RESISTANCE") },
            levels.support?.let { GlossaryEntry(stringResource(id = R.string.stock_detail_support_label), "SUPPORT") },
            levels.fairValueAnchor?.let { GlossaryEntry(stringResource(id = R.string.stock_detail_fair_value_anchor_label), "FAIR_VALUE_ANCHOR") },
            if (levels.accumulationZoneLow != null && levels.distributionZoneHigh != null) {
                GlossaryEntry(stringResource(id = R.string.stock_detail_value_area_label), "VALUE_AREA")
            } else null
        )
        StockAnalysisGlossaryBottomSheet(title = title, entries = entries, onDismiss = { showGlossary = false })
    }
}

@Composable
private fun LevelStat(value: Double?, label: String, modifier: Modifier = Modifier, valueColor: androidx.compose.ui.graphics.Color = MaterialTheme.colorScheme.onSurface) {
    if (value == null) return

    Column(modifier = modifier) {
        Text(
            text = "$${formatPrice(value)}",
            style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
            color = valueColor
        )
        Text(
            text = label,
            style = MaterialTheme.typography.labelSmall,
            color = LocalPulseColors.current.onSurfaceMuted
        )
    }
}

private fun formatPrice(value: Double): String = String.format(Locale.US, "%.2f", value)

@Composable
private fun Spacer() {
    androidx.compose.foundation.layout.Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_large)))
}

